pragma solidity >=0.8.0;

contract IntSemantics {
    int64 public b;

    function shiftNeg(int8 x) public {
        b = int64(uint8(x) >> 1);
    }
}

pragma solidity >=0.8.0;

contract EventProbe {
    event One(address indexed who);
    event Two(address indexed who, uint256 indexed val);
    event Three(address indexed who, uint256 indexed a, bytes32 indexed b);
    event Dyn(string indexed tag, uint256 val);
    event Plain(uint256 x, string message);

    uint256 public count;

    constructor() {
        count = 1;
        emit One(msg.sender);
        emit Plain(100, "ctor");
    }

    function emitAll(uint256 v, string calldata tag) external {
        count += 1;
        emit One(msg.sender);
        emit Two(msg.sender, v);
        emit Three(msg.sender, v, keccak256(bytes(tag)));
        emit Dyn(tag, v + 1);
        emit Plain(v, tag);
        emit One(msg.sender);
    }

    function emitRepeat(uint256 rounds) external {
        for (uint256 i = 0; i < rounds; i++) {
            count += 1;
            emit Two(msg.sender, i);
            emit Two(msg.sender, i);
        }
    }
}

pragma solidity >=0.8.0;

contract RevertReasonProbe {
    function underflow() external pure returns (uint256) {
        uint256 a;
        return a - 1;
    }
}

pragma solidity >=0.8.0;

contract LoopEventCapture {
    uint256 public count;

    event Val(uint256 v);
    event Pair(uint256 i, uint256 tenx);

    // Emits the raw loop counter each iteration.
    // Expected (spec) sequence for n=3: Val(0), Val(1), Val(2).
    function counterLoop(uint256 n) external {
        for (uint256 i = 0; i < n; i++) {
            emit Val(i);
            count++;
        }
    }

    // Emits an accumulator that is NOT the loop counter.
    // Expected (spec) sequence for n=3: Val(0), Val(1), Val(3).
    function accumLoop(uint256 n) external {
        uint256 acc = 0;
        for (uint256 i = 0; i < n; i++) {
            acc += i;
            emit Val(acc);
        }
        count += n;
    }

    // Emits a derived per-iteration expression alongside the counter.
    // Expected (spec) sequence for n=3: Pair(0,0), Pair(1,10), Pair(2,20).
    function derivedLoop(uint256 n) external {
        for (uint256 i = 0; i < n; i++) {
            emit Pair(i, i * 10);
        }
        count += n;
    }
}

pragma solidity >=0.8.0;
contract ValueForwardProbe {
    uint256 public count;

    function deposit() external payable {
        count++;
    }

    function forward(address payable to, uint256 amt) external {
        count++;
        (bool ok,) = to.call{value: amt}("");
        require(ok);
        count += 10;
    }

    function myBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

pragma solidity >=0.8.0;

contract StringBytesRoundtrip {
    string public storedString;
    bytes public storedBytes;
    uint256 public count;

    function setString(string memory s) public {
        storedString = s;
        count += 1;
    }

    function setBytes(bytes memory b) public {
        storedBytes = b;
        count += 1;
    }

    function getString() public view returns (string memory) {
        return storedString;
    }

    function getBytes() public view returns (bytes memory) {
        return storedBytes;
    }

    function getStringLen() public view returns (uint256) {
        return bytes(storedString).length;
    }

    function getBytesLen() public view returns (uint256) {
        return storedBytes.length;
    }
}
